    {
        var statusElement = document.getElementById("rn_" + this.instanceID +"_Status");
        if(!statusElement)
            return;

        //update status
        switch(this._currentState)
        {
            case RightNow.Chat.Model.ChatState.SEARCHING:
            case RightNow.Chat.Model.ChatState.REQUEUED:
            {
                statusElement.innerHTML = this.data.attrs.label_status_searching;
                break;
            }
            case RightNow.Chat.Model.ChatState.CONNECTED:
            {
                statusElement.innerHTML = this.data.attrs.label_status_connected;
                break;
            }
            case RightNow.Chat.Model.ChatState.RECONNECTING:
            {
                if(this._previousState === RightNow.Chat.Model.CONNECTED)
                    statusElement.innerHTML = this.data.attrs.label_status_reconnecting;

                break;
            }
            case RightNow.Chat.Model.ChatState.CANCELLED:
            case RightNow.Chat.Model.ChatState.DEQUEUED:
            {
                statusElement.innerHTML = this.data.attrs.label_status_canceled;
                break;
            }
            case RightNow.Chat.Model.ChatState.DISCONNECTED:
            {
                if(this._reason && this._reason === 'RECONNECT_FAILED')
                    statusElement.innerHTML = RightNow.Interface.getMessage("COMM_RN_LIVE_SERV_LOST_CHAT_SESS_MSG");
                else
                    statusElement.innerHTML = this.data.attrs.label_status_disconnected;
                break;
            }
        }
    },

