RightNow.Widget.ChatSoundButton = function(data, instanceID) {
    // Widget data section
    this.data = data;
    this.instanceID = instanceID;

    // Local member variables section
    this._container = document.getElementById('rn_' + this.instanceID);
    this._containerOn = document.getElementById('rn_' + this.instanceID + '_On');
    this._containerOff = document.getElementById('rn_' + this.instanceID + '_Off');
    this._soundButtonOn = document.getElementById("rn_" + this.instanceID + "_ButtonOn");
    this._soundButtonOff = document.getElementById("rn_" + this.instanceID + "_ButtonOff");
    this._flashEnabled = false;
    this._receiveSound = document.createElement('audio');

    var soundSupported = false;

    // Check for support. First, try HTML5 audio. Fallback to flash.
    if(this._receiveSound && this._receiveSound.canPlayType && (this._receiveSound.canPlayType('audio/ogg') || this._receiveSound.canPlayType('audio/x-wav')))
    {
        // Select the correct audio file to play, based on supported codec. Prioritize ogg for its smaller size and broader support.
        var audioSource = document.createElement('source');
        audioSource.src = this._receiveSound.canPlayType('audio/ogg') ? this.data.attrs.receive_sound_ogg_path : this.data.attrs.receive_sound_wav_path;
        this._receiveSound.appendChild(audioSource);

        soundSupported = true;
    }
    else if(this.data.attrs.enable_flash_support)
    {
        var userAgent = YAHOO.env.ua;

        if(userAgent.ie)
        {
            var activeXFlash = null;

            // Check for flash support via ActiveX; simple SWF audio should play in most (if not all) flash versions
            try
            {
                activeXFlash = new ActiveXObject("ShockwaveFlash.ShockwaveFlash.6");
                this._flashEnabled = true;
            }
            catch(e)
            {}

            if(activeXFlash === null)
            {
                try
                {
                    activeXFlash = new ActiveXObject("ShockwaveFlash.ShockwaveFlash");
                    this._flashEnabled = true;
                }
                catch(e)
                {}
            }
        }
        else
        {
            if(navigator.mimeTypes['application/x-shockwave-flash'])
                this._flashEnabled = true;
        }

        if(this._flashEnabled)
        {
            // SWF objects are dynamically created by setting the innerHTML of a DOM element. Other methods may fail.
            var flashObjectString = '<object id="rn_' + this.instanceID + '_ReceiveSoundFlash" ';

            if(userAgent.ie)
            {
                flashObjectString += 'classid="clsid:D27CDB6E-AE6D-11cf-96B8-444553540000">';
                flashObjectString += '<param name="movie" value="' + this.data.attrs.receive_sound_flash_path + '">';
            }
            else
            {
                flashObjectString += 'type="application/x-shockwave-flash" data="' + this.data.attrs.receive_sound_flash_path + '">';
            }

            flashObjectString += '<param name="allowScriptAccess" value="always">';
            flashObjectString += '<param name="loop" value="false">';
            flashObjectString += '<param name="play" value="false">';
            flashObjectString += '</object>';

            // Create hidden container for the flash object, within the widget container.
            var receiveFlashContainer = document.createElement('div');
            receiveFlashContainer.id = 'rn_' + this.instanceID + '_ReceiveSoundFlashContainer';
            receiveFlashContainer.innerHTML = flashObjectString;
            YAHOO.util.Dom.addClass(receiveFlashContainer, "rn_FlashContainer");
            this._container.appendChild(receiveFlashContainer);

            this._receiveSound = document.getElementById('rn_' + this.instanceID + '_ReceiveSoundFlash');

            soundSupported = true;
