    {
        var currentState = args[0].data.currentState;
        var previousState = args[0].data.previousState;
        var ChatState = RightNow.Chat.Model.ChatState;

        if(currentState === ChatState.CONNECTED && previousState !== ChatState.CONNECTED)
        {
            YAHOO.util.Dom.removeClass(this._container, 'rn_Hidden');
        }
        else if(currentState === ChatState.CANCELLED || currentState === ChatState.DISCONNECTED)
        {
            if(this.data.attrs.mobile_mode)
                YAHOO.util.Dom.addClass(this._container, 'rn_Hidden');
            else
            {
                this._disconnectButton.innerHTML = (this.data.attrs.close_icon_path === '' ? '' : '<img src="' + this.data.attrs.close_icon_path + '" /> ') + this.data.attrs.label_close;
                this._disconnectButton.title = this.data.attrs.label_tooltip_close;
            }
        }
        else if(currentState === ChatState.REQUEUED)
            YAHOO.util.Dom.addClass(this._container, 'rn_Hidden');

        this._currentState = currentState;
