RightNow.Widget.SearchSuggestions2.prototype = {
    /**
     * Event handler for when search suggestions were found
     * @param {String} type Event name
     * @param {Object} args Event arguments
     */
    _onSuggestionResponse: function(type, args)
    {
        var eventObject = args[0];
        if(eventObject.data.related_prods.length || eventObject.data.related_cats.length)
        {
            var suggestionContent = "",
                parameterList = "";
            if(eventObject.filters && eventObject.filters.allFilters && eventObject.filters.allFilters.format)
            {
                eventObject.filters.allFilters.format.parmList = this.data.attrs.add_params_to_url;
                parameterList = RightNow.Url.buildUrlLinkString(eventObject.filters.allFilters);
            }
            if(eventObject.data.related_prods.length)
            {
                var products = eventObject.data.related_prods;
                for (var i = 0; i < products.length; i++)
                {
                    if(typeof products[i] !== "function")
                        suggestionContent += "<li><a href='" + this.data.attrs.report_page_url + '/' + this.data.js.productFilter + '/' + products[i].id + parameterList + "'/>" + products[i].label + "</a>";
                }
            }
            if (eventObject.data.related_cats.length)
            {
                var categories = eventObject.data.related_cats;
                for (var i = 0; i < categories.length; i++)
                {
                    if(typeof categories[1] !== "function")
                        suggestionContent += "<li><a href='" + this.data.attrs.report_page_url + '/' + this.data.js.categoryFilter + '/' + categories[i].id + parameterList + "'/>" + categories[i].label + "</a>";
                }
            }
            var suggestionsList = document.getElementById("rn_" + this.instanceID + "_SuggestionsList");
            var root = document.getElementById("rn_" + this.instanceID);
            if(!suggestionsList)
            {
                suggestionsList = document.createElement("UL");
                suggestionsList.id = "rn_" + this.instanceID + "_SuggestionsList";
            }
            suggestionsList.innerHTML = suggestionContent;
            if(root)
                root.appendChild(suggestionsList);
            YAHOO.util.Dom.removeClass("rn_" + this.instanceID, "rn_Hidden");
        }
        else
        {
            YAHOO.util.Dom.addClass("rn_" + this.instanceID, "rn_Hidden");
        }
    }
};

