    delete this.data.js.guidedAssistant;
    //flags for agent mode-checking basura:
    this._isConsoleMode = (typeof this.data.js.agentMode !== "undefined");
    this._isAgentRuntime = (this.data.js.agentMode === "agent");
    this._isAPreviewMode = (this.data.js.agentMode && this.data.js.agentMode.toLowerCase().indexOf("preview") > -1);
    this._isEnduserPreviewMode = (this.data.js.agentMode && this.data.js.agentMode === "enduserPreview");

    var RightNowEvent = RightNow.Event;
    RightNowEvent.subscribe("evt_GuidedAssistanceResponse", this._getGuideResponse, this);
    RightNowEvent.subscribe("evt_GuidedAssistanceGoToResponse", this._goToResponse, this);
    RightNowEvent.subscribe("evt_GuidedAssistanceGoToQuestion", this._goToQuestion, this);
    RightNowEvent.subscribe("evt_GuidedAssistanceAnswerViewed", this._answerViewed, this);

    var ariaDiv = document.createElement("div");
    ariaDiv.className = "rn_ScreenReaderOnly";
    ariaDiv.setAttribute("role", "alert");
    this._liveNotificationArea = document.body.appendChild(ariaDiv);

    YAHOO.util.Event.addListener("rn_" + this.instanceID + "_BackButton", "click", this._goBackHelper, null, this);

    var recordGuideSessionStart = function(){
        //Submit stats for this session
        this._submitStats(RightNow.Ajax.CT.GA_SESSIONS, 
            {"ga_sid": this._guide[this._currentGuideID].guideSessionID, "ga_id": this._currentGuideID, "sid": this.data.js.session, "acct_id": parseInt(this.data.js.accountID, 10), "channel": this.data.js.channel},
            true);
        //Submit stats for the initially displayed question
        this._submitStats(RightNow.Ajax.CT.GA_SESSION_DETAILS, 
            {"ga_sid": this._guide[this._currentGuideID].guideSessionID, "ga_id": this._currentGuideID, "q_id": this._currentQuestion});
    };

    if(top === self && !this._isConsoleMode && !RightNowEvent.isHistoryManagerFragment()){
        var History = YAHOO.util.History;
        this._stateKey = "gs";
        History.register(this._stateKey, History.getBookmarkedState(this._stateKey) || "", function(state){
           this._restoreState(state); 
        }, this, true);
        History.onReady(function(){
            var currentState = History.getCurrentState(this._stateKey);
            if(currentState){
                if(this._restoreState(currentState)){
                    return;
                }
                else{
                    History.navigate(this._stateKey, "");
                }
            }
            recordGuideSessionStart.call(this);
        }, this, true);
        try{
            History.initialize("rn_History_Field", "rn_History_Iframe");
        }
        catch(e){
            //prehistoric browser
            this._stateKey = null;
            recordGuideSessionStart.call(this);
        }
    }
    else{
        recordGuideSessionStart.call(this);
    }

    //notify listeners that a guide has been loaded
    this._eo.data = {"guideID": this._currentGuideID};
    RightNowEvent.fire("evt_GuideLoaded", this._eo);
};

